import base64, re

# The base64 HTML from renderChart result
b64 = ""

html = base64.b64decode(b64).decode("utf-8")
match = re.search(r"<svg[^>]*>.*?</svg>", html, re.DOTALL)
if match:
    svg = match.group()
    with open("/workspace/report/Top10_Movies_by_Average_Rating_chart.svg", "w", encoding="utf-8") as f:
        f.write(svg)
    print("SVG saved successfully, length:", len(svg))
else:
    print("SVG not found")
